import "dotenv/config";
import bcrypt from "bcryptjs";
import { randomUUID } from "node:crypto";
import { eq, inArray } from "drizzle-orm";
import { db } from "../config/db.js";
import { MIN_PASSWORD_LENGTH } from "../config/security.js";
import { employees, roles, userRoles, users } from "../db/schema.js";
import { normalizeLoginCuit } from "../services/login-identity.service.js";
const [cuitInput, password] = process.argv.slice(2);
const cuit = normalizeLoginCuit(cuitInput);
if (!cuit || !password || password.length < MIN_PASSWORD_LENGTH) throw new Error(`Uso: pnpm bootstrap-admin <CUIT> <contraseña de al menos ${MIN_PASSWORD_LENGTH} caracteres>`);
const [employee] = await db.select().from(employees).where(eq(employees.cuitNormalized, cuit));
if (!employee || !employee.active) throw new Error("Debe existir un empleado activo con ese CUIT antes de crear la cuenta administrativa");
if (employee.userId) throw new Error("El empleado ya tiene una cuenta asociada");
const bootstrapRoles = await db.select().from(roles).where(inArray(roles.name, ["ADMIN", "EMPLOYEE"]));
const adminRole = bootstrapRoles.find((role) => role.name === "ADMIN");
const employeeRole = bootstrapRoles.find((role) => role.name === "EMPLOYEE");
if (!adminRole || !employeeRole) throw new Error("Ejecute primero el seed");
const id = randomUUID(); await db.insert(users).values({ id, passwordHash: await bcrypt.hash(password, 12), mustChangePassword: true }); await db.update(employees).set({ userId: id, updatedAt: new Date() }).where(eq(employees.id, employee.id)); await db.insert(userRoles).values([{ userId:id, roleId:adminRole.id }, { userId:id, roleId:employeeRole.id }]); console.log("ADMIN creado. Debe cambiar su contraseña al iniciar sesión con su CUIT.");
